### 代码原文
```ts
146    //==========================================================
147    //M 按配置顺序发起挂载并限时等待
148    //==========================================================
149    for (const entry of entries) {
150      //M 先按配置名找内置插件，也为加载失败的状态记录注入声明。
151      const builtIn = pluginIndex.BUILT_IN[entry.name];
152      const row: resourcesModule.PluginStatus = {
153        name: entry.name,
154        mounted: false,
155        started: false,
156        missing: [],
157        error: '',
158        inject: builtIn?.inject ?? [],
159      };
160      try {
161        let plugin = builtIn;
162        if (plugin === undefined) {
163          //M 内置表查不到才从外部插件文件夹加载入口。
164          const root = app.resources.root;
165          plugin = await loadExternalPlugin(entry.name, root);
166        }
167  
168        //M 等待 Cordis apply。状态监听使用 thenable 后面的原 fiber。
169        row.inject = plugin.inject ?? [];
170        const mounted = app.plugin(plugin, entry.config);
171        const fiber = mounted.ctx.fiber;
172        starting.set(fiber, row);
173  
174        //M 首次等待结束时也可能在等注入。异步失败即使发生在超时之后也照常记账。
175        const finished = fiber.await().then(() => {
176          if (fiber.state === cordis.FiberState.PENDING && row.error === '') {
177            row.mounted = true;
178          }
179          return true;
180        }, (error: unknown) => {
181          if (starting.delete(fiber)) {
182            recordPluginFailure(row, error);
183          }
184          return true;
185        });
186  
187        const timer = new AbortController();
188        const options = { signal: timer.signal };
189        const deadline = timers.setTimeout(pluginMountTimeoutMs, false, options);
190        const waiting = [finished, deadline];
191        try {
192          const inTime = await Promise.race(waiting);
193          if (!inTime && starting.has(fiber)) {
194            //G 到点只结束本次等待。保留 fiber，让它完成后还能发状态和服务通知。
195            const seconds = pluginMountTimeoutMs / 1000;
196            row.mounted = false;
197            row.error = `启动超过 ${String(seconds)} 秒，先挂后面的，它继续在后台起`;
198            console.error(`插件 ${row.name} ${row.error}`);
199          }
200        } finally {
201          timer.abort();
202        }
203      } catch (error) {
204        recordPluginFailure(row, error);
205      }
206      //M 维持配置顺序，每次发起挂载只占一行，供 health 和启动流程读。
207      app.resources.pluginStatus.push(row);
208    }
209  
```

### 解释
- L149：照配置先后一个个来。
- 每项只在 pluginStatus 里占一行（L207），供 health 和教程读。

