235  /**
236   * 从外部插件文件夹加载入口，优先使用 index.ts，再找 index.js。
237   * @param name 外部插件的文件夹路径，相对路径从运行时目录算。
238   * @param root 配置所在的运行时目录。
239   * @returns 这个插件的模块（导出 name、inject、apply）。导出得不对，Cordis 挂它的时候会报错。
240   */
241  async function loadExternalPlugin(name: string, root: string): Promise<pluginIndex.PluginModule> {
242    //M 按运行时目录解析外部路径，保留已有的入口优先级。
243    const dir = path.resolve(root, name);
244    let entry = path.join(dir, 'index.ts');
245    if (!fs.existsSync(entry)) {
246      entry = path.join(dir, 'index.js');
247    }
248  
249    //M 动态 import 认的是网址：路径先转成 file:// 网址，Windows 的盘符路径才不会被当成别的协议。
250    const entryUrl = pathToFileURL(entry).href;
251    const loaded = await import(entryUrl) as pluginIndex.PluginModule & {
252      default?: pluginIndex.PluginModule;
253    };
254  
255    //M 模块有 default 导出就用 default（DSH 的加载器也是这么做的）。
256    return loaded.default ?? loaded;
257  }
258  
259  
```

